<?php require 'config.php'; require_login(); verify_csrf();$u=current_user();if($_SERVER['REQUEST_METHOD']==='POST'){ $users=read_json('users.json',[]);foreach($users as &$x)if($x['id']===$u['id']){$x['name']=trim($_POST['name']);$x['address']=trim($_POST['address']);}write_json('users.json',$users);flash('تم تحديث البيانات.');redirect('profile.php');}$title='حسابي';require 'header.php';?><div class="form"><h1>حسابي</h1><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input name="name" value="<?=e($u['name'])?>" required><input value="<?=e($u['phone'])?>" disabled><input name="address" value="<?=e($u['address']??'')?>" placeholder="العنوان"><button class="btn">حفظ</button></form></div><?php require 'footer.php';?>